package com.enterprise.siem.database;
import com.enterprise.siem.model.*; import java.sql.*; import java.time.Instant; import java.util.Optional; import java.util.UUID;
public final class IncidentRepository { private final DatabaseManager db; public IncidentRepository(DatabaseManager db) { this.db=db; }
 public void save(Incident i) throws SQLException { synchronized(db.writeLock()){try (PreparedStatement p=db.connection().prepareStatement("INSERT INTO incidents(incident_id,created_at,severity,title,description,status,response_action,updated_at,resolved_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(incident_id) DO UPDATE SET status=excluded.status,updated_at=excluded.updated_at,resolved_at=excluded.resolved_at")) { p.setString(1,i.incidentId().toString());p.setString(2,i.createdAt().toString());p.setString(3,i.severity().name());p.setString(4,i.title());p.setString(5,i.description());p.setString(6,i.status());p.setString(7,i.responseAction());p.setString(8,i.updatedAt().toString());p.setString(9,i.resolvedAt()==null?null:i.resolvedAt().toString());p.executeUpdate(); } } }
 public void linkAlert(Incident incident, com.enterprise.siem.model.Alert alert) throws SQLException { synchronized(db.writeLock()){try(PreparedStatement p=db.connection().prepareStatement("INSERT OR IGNORE INTO incident_alerts(incident_id,alert_id,linked_at) VALUES(?,?,?)")){p.setString(1,incident.incidentId().toString());p.setString(2,alert.alertId().toString());p.setString(3,java.time.Instant.now().toString());p.executeUpdate();}} }
 public Optional<Incident> find(UUID id) throws SQLException { synchronized(db.writeLock()){try(PreparedStatement p=db.connection().prepareStatement("SELECT incident_id,created_at,updated_at,resolved_at,severity,title,description,status,response_action FROM incidents WHERE incident_id=?")){p.setString(1,id.toString());try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();return Optional.of(new Incident(UUID.fromString(r.getString(1)),Instant.parse(r.getString(2)),r.getString(3)==null?null:Instant.parse(r.getString(3)),r.getString(4)==null?null:Instant.parse(r.getString(4)),Severity.valueOf(r.getString(5)),r.getString(6),r.getString(7),r.getString(8),r.getString(9)));}}} }
}
